CREATE OR REPLACE FUNCTION public.validate_plan_level() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF NEW.required_level <> 'any' AND (TG_OP='INSERT' OR NEW.required_level IS DISTINCT FROM OLD.required_level) AND NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=NEW.host_id AND demo_plus) THEN RAISE EXCEPTION 'Juntos Plus is required to set a proficiency level'; END IF; RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.limit_free_alerts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.user_id::text)); IF NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=NEW.user_id AND demo_plus) AND (SELECT count(*) FROM public.saved_alerts WHERE user_id=NEW.user_id)>=2 THEN RAISE EXCEPTION 'Free includes 2 saved alerts. Switch to Juntos Plus for unlimited alerts.'; END IF; RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.gate_host_tools() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF NEW.host_id IS NOT NULL AND NOT NEW.is_example AND (NEW.recurring_weekly OR NEW.auto_approve OR NEW.capacity>8 OR NEW.early_booking) AND (TG_OP='INSERT' OR NEW.recurring_weekly IS DISTINCT FROM OLD.recurring_weekly OR NEW.auto_approve IS DISTINCT FROM OLD.auto_approve OR NEW.capacity IS DISTINCT FROM OLD.capacity OR NEW.early_booking IS DISTINCT FROM OLD.early_booking) AND NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=NEW.host_id AND demo_plus) THEN RAISE EXCEPTION 'Juntos Plus is required for advanced host tools'; END IF; RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.validate_private_age() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $function$ BEGIN IF NEW.date_of_birth IS NOT NULL AND (NEW.date_of_birth>current_date-interval '18 years' OR NEW.date_of_birth<current_date-interval '120 years') THEN RAISE EXCEPTION 'Juntos is for adults aged 18 and over.'; END IF; IF TG_OP='UPDATE' AND NEW.date_of_birth IS DISTINCT FROM OLD.date_of_birth THEN NEW.age_verified:=false; END IF; IF NEW.meet_age_min IS NOT NULL AND (NEW.meet_age_min<18 OR NEW.meet_age_min>120) OR NEW.meet_age_max IS NOT NULL AND (NEW.meet_age_max<coalesce(NEW.meet_age_min,18) OR NEW.meet_age_max>120) THEN RAISE EXCEPTION 'Choose an adult age bracket.'; END IF; RETURN NEW; END $function$;